WITH m0 AS (SELECT SUM((lines.gross_sales_cents - lines.discount_cents) * 0.01) AS lines_gross_sales_cents_discount_cents_0_01_sum FROM (SELECT l.* FROM commerce.fct_order_lines AS l JOIN commerce.fct_orders AS o ON l.order_id = o.order_id JOIN crm.dim_customer AS c ON o.customer_id = c.customer_id WHERE o.status = 'delivered' AND NOT o.is_test AND o.delivered_at >= CAST('2025-09-20' AS DATE) AND o.delivered_at < CAST('2026-09-20' AS DATE) AND NOT c.is_employee AND c.identity_status = 'resolved' AND l.delivered_qty > 0) AS lines), m1 AS (SELECT SUM(refunds.merchandise_refund_cents * 0.01) AS refunds_merchandise_refund_cents_0_01_sum FROM (SELECT a.*, o.customer_id AS customer_id FROM finance.fct_refund_events AS a JOIN commerce.fct_order_lines AS l ON a.order_line_id = l.order_line_id JOIN commerce.fct_orders AS o ON l.order_id = o.order_id JOIN crm.dim_customer AS c ON o.customer_id = c.customer_id WHERE o.status = 'delivered' AND NOT o.is_test AND o.delivered_at >= CAST('2025-09-20' AS DATE) AND o.delivered_at < CAST('2026-09-20' AS DATE) AND NOT c.is_employee AND c.identity_status = 'resolved' AND l.delivered_qty > 0 AND a.status = 'posted' AND a.posted_at < CAST('2026-10-20' AS DATE)) AS refunds), m2 AS (SELECT SUM(line_costs.cogs_cents * 0.01) AS line_costs_cogs_cents_0_01_sum, SUM(line_costs.payment_fee_cents * 0.01) AS line_costs_payment_fee_cents_0_01_sum FROM (SELECT a.* FROM finance.fct_order_line_costs AS a JOIN commerce.fct_order_lines AS l ON a.order_line_id = l.order_line_id JOIN commerce.fct_orders AS o ON l.order_id = o.order_id JOIN crm.dim_customer AS c ON o.customer_id = c.customer_id WHERE o.status = 'delivered' AND NOT o.is_test AND o.delivered_at >= CAST('2025-09-20' AS DATE) AND o.delivered_at < CAST('2026-09-20' AS DATE) AND NOT c.is_employee AND c.identity_status = 'resolved' AND l.delivered_qty > 0) AS line_costs), m3 AS (SELECT SUM(returns.recoverable_cogs_credit_cents * 0.01) AS returns_recoverable_cogs_credit_cents_0_01_sum, SUM(returns.processing_cost_cents * 0.01) AS returns_processing_cost_cents_0_01_sum FROM (SELECT a.* FROM returns.fct_return_events AS a JOIN commerce.fct_order_lines AS l ON a.order_line_id = l.order_line_id JOIN commerce.fct_orders AS o ON l.order_id = o.order_id JOIN crm.dim_customer AS c ON o.customer_id = c.customer_id WHERE o.status = 'delivered' AND NOT o.is_test AND o.delivered_at >= CAST('2025-09-20' AS DATE) AND o.delivered_at < CAST('2026-09-20' AS DATE) AND NOT c.is_employee AND c.identity_status = 'resolved' AND l.delivered_qty > 0 AND a.status = 'received' AND a.received_at < CAST('2026-10-20' AS DATE)) AS returns), m4 AS (SELECT SUM(deliveries.shipping_cost_cents * 0.01) AS deliveries_shipping_cost_cents_0_01_sum FROM (SELECT d.* FROM logistics.fct_order_logistics AS d JOIN commerce.fct_orders AS o USING (order_id) JOIN crm.dim_customer AS c USING (customer_id) WHERE o.status = 'delivered' AND NOT o.is_test AND o.delivered_at >= CAST('2025-09-20' AS DATE) AND o.delivered_at < CAST('2026-09-20' AS DATE) AND NOT c.is_employee AND c.identity_status = 'resolved') AS deliveries), m5 AS (SELECT COUNT(DISTINCT orders.order_id) AS orders_order_id_count_distinct, COUNT(DISTINCT CASE WHEN orders.is_returned THEN orders.order_id END) AS orders_case_when_is_returned_then_order_id_end_count_distinct FROM (SELECT o.* FROM commerce.fct_orders AS o JOIN crm.dim_customer AS c USING (customer_id) WHERE o.status = 'delivered' AND NOT o.is_test AND o.delivered_at >= CAST('2025-09-20' AS DATE) AND o.delivered_at < CAST('2026-09-20' AS DATE) AND NOT c.is_employee AND c.identity_status = 'resolved' AND EXISTS(SELECT 1 FROM commerce.fct_order_lines AS l WHERE l.order_id = o.order_id AND l.delivered_qty > 0)) AS orders) SELECT COALESCE(m0.lines_gross_sales_cents_discount_cents_0_01_sum, 0) - COALESCE(m1.refunds_merchandise_refund_cents_0_01_sum, 0) - COALESCE(m2.line_costs_cogs_cents_0_01_sum, 0) + COALESCE(m3.returns_recoverable_cogs_credit_cents_0_01_sum, 0) - COALESCE(m4.deliveries_shipping_cost_cents_0_01_sum, 0) - COALESCE(m2.line_costs_payment_fee_cents_0_01_sum, 0) - COALESCE(m3.returns_processing_cost_cents_0_01_sum, 0) AS contribution_margin, COALESCE(m5.orders_order_id_count_distinct, 0) AS order_count, COALESCE(m5.orders_case_when_is_returned_then_order_id_end_count_distinct, 0) AS returned_order_count, m5.orders_case_when_is_returned_then_order_id_end_count_distinct * 1.0 / NULLIF(m5.orders_order_id_count_distinct, 0) AS order_return_rate FROM m0 CROSS JOIN m1 CROSS JOIN m2 CROSS JOIN m3 CROSS JOIN m4 CROSS JOIN m5;
